**Then, combine with those variables in equations (A1) and (A2) to estimate DLR; 
proc sql;
create table call_5 as select distinct a.*, b.llp, b.d_npl, b.lag1_d_npl, b.lag2_d_npl, b.lead1_d_npl, b.ebllp, b.lag_lnat,
b.lag_tieronecap, b.g_index 
from call_4 as a left join call_1 as b
on a.rssd9001 = b.rssd9001 and a.date = b.date;
quit;

data call_6; set call_5;
if rankdate>'30sep2000'd;
run;

proc sort data=call_6; by rssd9001 rankdate; quit; 

***Estimate equation (A1);
proc reg data=call_6 noprint adjrsq outest=estimates1;
by rssd9001 rankdate;
model llp = lag2_d_npl lag1_d_npl ebllp lag_tieronecap lag_lnat g_index;
options nonotes; quit;

data estimates1; set estimates1;
if _edf_>=5; /*require the bank to have data for all 12 quarters*/
run;

***Estimate equation (A2);
proc reg data=call_6 noprint adjrsq outest=estimates2;
by rssd9001 rankdate;
model llp = lag2_d_npl lag1_d_npl d_npl lead1_d_npl ebllp lag_tieronecap lag_lnat g_index;
options nonotes; quit;

data estimates2; set estimates2;
if _edf_>=3; /*require the bank to have data for all 12 quarters*/
run;

proc sql;
create table estimates1 as select distinct a.*, b._ADJRSQ_ as _ADJRSQ_2
from estimates1 as a left join estimates2 as b
on a.rssd9001 = b.rssd9001 and a.rankdate = b.rankdate;
quit;

***Take the difference between Adj. R2s of equations (A1) and (A2);
data estimates1; set estimates1;
delr=_ADJRSQ_-_ADJRSQ_2;
year=year(rankdate);
if delr=. then delete;
run;

*import Dataquick transaction data;
data transact_2; set dlr.transact;
if sr_property_id=. then delete;
if sr_tran_type in ('S','R');
if sr_arms_length_flag='1';
if mm_fips_state_code=. or mm_fips_state_code=2 or mm_fips_state_code=15 or mm_fips_state_code=66 or mm_fips_state_code=69 or mm_fips_state_code=72 or mm_fips_state_code=78 then delete;
year=year(sr_date_transfer);
if year(sr_date_transfer) < 2004 or year(sr_date_transfer) > 2010 then delete;
run;

*Combine the transaction data with the assess data;
proc sql;
create table transact_2 as select a.*, b.sa_property_id, b.sa_site_zip
from transact_2 as a left join dlr.assess as b
on a.sr_property_id = b.sa_property_id; 
quit;

*Delete observations without property id and ZIP-code id;
data transact_3; set transact_2;
if sa_property_id=. or sa_site_zip=. or sr_unique_id=. then delete;
if sa_site_zip=0 then delete;
run;

*Import the HMDA data of 2004 - 2010;
data hmda_2(drop=ethnic_co race2-race5 race_co1-race_co5 sex_co denial1-denial3 spread edit VAR38_ popul minority
med_income income_pct ownerunit familyunit date preapprove hoepa); set hmda.hmda_2004-hmda.hmda_2010; 
if state=. or state=2 or state=15 or state=66 or state=69 or state=72 or state=78 then delete;
if action=. or MSA="" or county="" or race1=. or loantype=. or propertytype=. or lien=. or sex=. or ethnic=. or occupancy=. then delete; 
if action=1;
if amount <=1 then delete;
if income <=10 then delete;
if loanpurpose in (1,3);
if loantype in (1,2);
if loantype=1 then conventional=1; else conventional=0;
if loantype=2 then fha=1; else fha=0;
if purchaser=0 then sold=0; else sold=1;
if propertytype=1 ;
if agency=7 then nonbank=1; else nonbank=0;
census_tract=tract*100;
state_new = put(state,2.);
fips1 = cat(state_new,county); 
fips_code = fips1*1;
drop fips1 state_new;
run;

*Import the HMDA data of 2001 - 2003 (This step is necessary because formats of several variables became different since 2004);
data hmda_2pre(drop=ethnic_co race2-race5 race_co1-race_co5 sex_co denial1-denial3 spread edit VAR38_); set hmda.hmda_2001-hmda.hmda_2003; 
if state=. or state=2 or state=15 or state=66 or state=69 or state=72 or state=78 then delete;
if action=. or MSA="" or county="" or race1=. or loantype=. or sex=. then delete; 
if action=1;
if amount <=1 then delete;
if income <=10 then delete;
if loanpurpose in (1,3);
if loantype in (1,2);
if loantype=1 then conventional=1; else conventional=0;
if loantype=2 then fha=1; else fha=0;
if purchaser=0 then sold=0; else sold=1;
if agency=7 then nonbank=1; else nonbank=0;
census_tract=tract*100;
state_new = put(state,2.);
fips1 = cat(state_new,county); 
fips_code = fips1*1;
drop fips1 state_new;
run;

*Combine two HMDA data sets;
data hmda_2; set hmda_2pre hmda_2; 
run;

*Import the link file between census tracts to ZIP codes;
proc sql;
create table hmda_2a as select a.*, b.zcta5
from hmda_2 as a left join dlr.link_zip1 as b
on a.fips_code = b.fips_code and a.census_tract = b.tract; 
quit;

data coincident_quarterly; set dlr.coincident_quarterly; 
year=year(date);
quarter=qtr(date);
run;

proc sql;
create table call_1 as select distinct a.*, b.g_index 
from call_1 as a left join coincident_quarterly as b
on a.rssd9200 = b.state and a.year = b.year and a.quarter = b.quarter;

proc sql;
create table delr_call_2 as select a.*, b.permco as permco1, b.dt_start as dt_start1, b.dt_end as dt_end1
from delr_call_1 as a left join dlr.link_crsp as b
on a.rssd9001 = b.entity; 
quit;

proc sql;
create table delr_call_2 as select a.*, b.permco as permco2, b.dt_start as dt_start2, b.dt_end as dt_end2
from delr_call_2 as a left join dlr.link_crsp as b
on a.rssd9348 = b.entity; 
quit;

proc sql;
create table delr_call_2 as select a.*, b.permco as permco3, b.dt_start as dt_start3, b.dt_end as dt_end3
from delr_call_2 as a left join dlr.link_crsp as b
on a.rssd9364 = b.entity;

*Import thresholds for jumbo loans by county and year;
proc sql;
create table hmda_2a as select a.*, b.one as one_1
from hmda_2a as a left join dlr.jumbo_2009_2016 as b
on a.year = b.year and a.fips_code = b.fips_code; 
quit;

proc sql;
create table hmda_2a as select a.*, b.one as one_2
from hmda_2a as a left join dlr.jumbo_2007_2008 as b
on a.year = b.year and a.fips_code = b.fips_code; 
quit;

proc sql;
create table hmda_2a as select a.*, b.one as one_3
from hmda_2a as a left join dlr.jumbo_1980_2007 as b
on a.year = b.year; 
quit;

**Create the jumbo loan indicator using the threshold;
data hmda_2a; set hmda_2a;
if one_2=. then one_2=one_3;
run;

data hmda_2a (drop=one_2 one_3); set hmda_2a;
if one_1=. then one_1=one_2;
run;

data hmda_2a; set hmda_2a;
if loantype=1 and amount>one_1 then jumbo=1; else jumbo=0;
if loantype=1 and amount<=one_1 then nonjumbo=1; else nonjumbo=0;

*Import the link file between Call Reports and HMDA using the reporter panel; 
proc sql;
create table hmda_2a as select a.*, b.respondent_rssd_id
from hmda_2a as a left join hmda.hmda_reporter_nac as b
on a.bankid = b.respondent_id and a.agency = b.agency_code and a.year = b.year; 
quit;

**Using 2004 infomation in the link file for years before 2004;
data hmda_reporter_nac; set hmda.hmda_reporter_nac; 
if year=2004;
run;

*Combine regional characteristics with the HMDA Data;
**Employment and Business Establishements from CBP;
proc sql;
create table hmda_8 as select a.*, b.g_emp, b.g_est
from hmda_7 as a left join dlr.cbp as b
on a.zcta5 = b.zipcode and a.year = b.year; 
quit;
**Income growth and average income from IRS;
proc sql;
create table hmda_8 as select a.*, b.g_gross_income, b.avg_income
from hmda_8 as a left join dlr.irs_all as b
on a.zcta5 = b.zipcode and a.year = b.year; 
quit;

***Fill in missing 2003 income with 2004 income;
data hmda_8; set hmda_8;
if year=2004 then g_gross_income_04=g_gross_income;
if year=2004 then avg_income_04=avg_income;
run;

proc sql;
create table hmda_8 as
select *, 
max(g_gross_income_04) as g_gross_income_max, max(avg_income_04) as avg_income_max 
from hmda_8
group by zcta5;
quit;

data hmda_8 (drop=g_gross_income_04 avg_income_04 g_gross_income_max avg_income_max); set hmda_8;
if year=2003 then g_gross_income=g_gross_income_max;
if year=2003 then avg_income=avg_income_max;
run;

**Demographics, poverty, and education data are from Census;
proc sql;
create table hmda_8 as select a.*, b.*
from hmda_8 as a left join dlr.census_zip as b
on a.zcta5 = b.zip_code; 
quit;

*Import two housing price indexes;
proc sql;
create table hmda_10 as select a.*, b.hpi as price1, b.d_hpi as d_price1
from hmda_10 as a left join dlr.hpi_fhfa_zip as b
on a.year = b.year and a.zcta5 = b.zip; 
quit;
proc sql;
create table hmda_10 as select a.*, b.HOME_PRICE_INDEX as price2, b.d_price2
from hmda_10 as a left join dlr.hpi_core_zip_2 as b
on a.year = b.year and a.zcta5 = b.zip_code; 
quit;

*Import population at county level;
proc sort data=hmda.Zcta_county_rel_10 out=Zcta_county_rel_10 nodupkey;
by state county;
run;

data hmda_12; set hmda_12;
county1=county*1;
run;

proc sql;
create table hmda_12 as select a.*, b.copop
from hmda_12 as a left join Zcta_county_rel_10 as b
on a.state = b.state and a.county1 = b.county;

proc sort data=hmda_13;
by zcta5 year;
run;

data dlr.hmda_13; set hmda_13;
run;

*Import DataQuick Loan data;
proc sql;
create table cleaned_2 as select a.*, b.sr_loan_val_1 as loan_val, b.sr_lndr_first_name_1 as lender_dq
from cleaned_1 as a left join dlr.loans as b
